import{_ as e,o as i,c as s,a2 as t}from"./chunks/framework.DCVnL8g5.js";const u=JSON.parse('{"title":"Particionado y optimización","description":"","frontmatter":{},"headers":[],"relativePath":"data-engineering/delta-lake/06-particionado-y-optimizacion.md","filePath":"data-engineering/delta-lake/06-particionado-y-optimizacion.md","lastUpdated":1789040978000,"isDraft":false}'),o={name:"data-engineering/delta-lake/06-particionado-y-optimizacion.md"};function n(r,a,l,d,p,c){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="particionado-y-optimizacion" tabindex="-1">Particionado y optimización <a class="header-anchor" href="#particionado-y-optimizacion" aria-label="Permalink to &quot;Particionado y optimización&quot;">​</a></h1><p>El snapshot puede ser correcto y las lecturas, caras. Los tres problemas habituales: <strong>demasiados ficheros pequeños</strong>, <strong>leer ficheros que el predicado no necesita</strong>, y <strong>particiones mal elegidas</strong> (demasiadas o ninguna cuando el filtro es estable).</p><p>Documentación: <a href="https://docs.delta.io/latest/optimizations-oss.html" target="_blank" rel="noreferrer">optimizaciones OSS</a>, <a href="https://docs.delta.io/latest/api/python/spark/index.html" target="_blank" rel="noreferrer">DeltaTable.optimize</a>.</p><h2 id="primero-el-layout-luego-la-herramienta" tabindex="-1">Primero el layout, luego la herramienta <a class="header-anchor" href="#primero-el-layout-luego-la-herramienta" aria-label="Permalink to &quot;Primero el layout, luego la herramienta&quot;">​</a></h2><p>Un stream que hace append cada pocos segundos deja miles de Parquet de 2 MB. <code>SELECT</code> sobre <code>/data/events</code> abre todos. Un <code>WHERE event_date = DATE &#39;2026-09-08&#39;</code> sin particionar ni estadísticas útiles lee de más. Un <code>PARTITIONED BY (user_id)</code> crea millones de directorios de un fichero.</p><p>Mide: número de ficheros (<code>DESCRIBE DETAIL</code>), tamaño medio, predicados reales de las queries. No “optimices” una tabla de laboratorio de 20 MB.</p><h2 id="particionar" tabindex="-1">Particionar <a class="header-anchor" href="#particionar" aria-label="Permalink to &quot;Particionar&quot;">​</a></h2><p>Particionar <strong>corta</strong> el árbol de directorios. Spark puede hacer <strong>partition pruning</strong>: si el plan ve <code>event_date = …</code>, no lista el resto de particiones.</p><p>Tiene sentido cuando:</p><ul><li>el filtro es casi siempre la misma columna de <strong>baja o media</strong> cardinalidad (<code>event_date</code>, <code>country</code>, <code>pipeline_date</code>);</li><li>cada partición acumula volumen (orientativamente cientos de MB o más, no 12 KB);</li><li>el DML (<code>DELETE</code>/<code>MERGE</code> del día) se acota a esas particiones.</li></ul><p>No particiones por <code>event_id</code>, email o timestamp a segundo. No copies “particionar por todas las columnas del WHERE”. Una columna de cardinalidad altísima destruye el listing y empeora el small-file problem.</p><p>El particionado se fija al crear (capítulo 2). Cambiarlo implica reescribir la tabla.</p><h2 id="data-skipping-partition-pruning" tabindex="-1">Data skipping ≠ partition pruning <a class="header-anchor" href="#data-skipping-partition-pruning" aria-label="Permalink to &quot;Data skipping ≠ partition pruning&quot;">​</a></h2><p>Al escribir, Delta guarda <strong>estadísticas por fichero</strong> (mínimo, máximo, nulls) de las primeras columnas del esquema (<code>delta.dataSkippingNumIndexedCols</code>; las columnas anidadas cuentan). En el plan, un <code>WHERE event_type = &#39;purchase&#39;</code> puede <strong>saltar ficheros</strong> cuyo min/max no cubre ese valor, <strong>aunque la tabla no esté particionada</strong>.</p><table tabindex="0"><thead><tr><th></th><th>Qué descarta</th><th>Dónde vive</th></tr></thead><tbody><tr><td><strong>Partition pruning</strong></td><td>Directorios enteros</td><td>Layout Hive-style</td></tr><tr><td><strong>Data skipping</strong></td><td>Ficheros dentro (o sin) particiones</td><td>Stats del log / footer</td></tr></tbody></table><p>No son lo mismo. Skipping funciona mejor si los valores de la columna filtrada <strong>no</strong> están mezclados en todos los ficheros (de ahí Z-Order). Strings/binarios largos son caros de estadificar: reordena columnas o baja <code>dataSkippingNumIndexedCols</code>.</p><p>No configuras skipping “on/off” por query: se aplica cuando las stats existen y el predicado es usable.</p><h2 id="compaction-optimize" tabindex="-1">Compaction: <code>OPTIMIZE</code> <a class="header-anchor" href="#compaction-optimize" aria-label="Permalink to &quot;Compaction: \`OPTIMIZE\`&quot;">​</a></h2><p>El <em>small-file problem</em> se ataca compactando: menos ficheros, mismo snapshot lógico.</p><p>En <strong>Delta Lake OSS</strong> existe <code>OPTIMIZE</code> (bin-packing). Los lectores no se rompen: isolation de snapshot; <code>OPTIMIZE</code> no cambia filas (<code>dataChange = false</code> en la compactación).</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPTIMIZE delta.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`/data/events\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPTIMIZE delta.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`/data/events\`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> event_date </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;2026-09-01&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> delta.tables </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DeltaTable</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DeltaTable.forPath(spark, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/data/events&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .optimize()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .where(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;event_date &gt;= &#39;2026-09-01&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .executeCompaction()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Compactar <strong>todo</strong> cada hora en una tabla de terabytes es un coste, no una virtud. Acota particiones calientes. Un stream que usa la tabla como source <strong>no</strong> se invalida porque <code>OPTIMIZE</code> reescriba ficheros.</p><p>En la página OSS aparecen también <em>auto compaction</em> y <em>optimized write</em>, con keys <code>spark.databricks.delta.autoCompact.*</code> / <code>optimizeWrite</code> y propiedades <code>delta.autoOptimize.*</code>. Son opciones del runtime Spark/Delta, no el producto Databricks “Auto Optimize” / Predictive Optimization. Si las usas, trátalas como <strong>tuning</strong>, no como sustituto de un <code>OPTIMIZE</code> consciente.</p><h2 id="z-ordering" tabindex="-1">Z-Ordering <a class="header-anchor" href="#z-ordering" aria-label="Permalink to &quot;Z-Ordering&quot;">​</a></h2><p><code>ZORDER BY</code> reorganiza filas <strong>dentro</strong> de los ficheros para colocalizar valores de una o pocas columnas muy filtradas (alta cardinalidad que <strong>no</strong> quieres como partición: <code>event_type</code> + <code>customer_id</code> en consultas puntuales). El data skipping aprovecha min/max más selectivos.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPTIMIZE events ZORDER </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (event_type);</span></span></code></pre></div><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> delta.tables </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DeltaTable</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DeltaTable.forPath(spark, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/data/events&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).optimize().executeZOrderBy(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;event_type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>No “Z-Order siempre mejora todo”. Cada columna extra diluye la localidad. Z-Order sobre una columna <strong>sin</strong> estadísticas es tirar CPU. No sustituye un esquema y un particionado razonables. Es un rewrite: cóstalo.</p><h2 id="clustering-moderno-alcance" tabindex="-1">Clustering moderno (alcance) <a class="header-anchor" href="#clustering-moderno-alcance" aria-label="Permalink to &quot;Clustering moderno (alcance)&quot;">​</a></h2><p>La table feature <strong>clustering</strong> (liquid clustering en la jerga) existe en Delta Lake reciente y <strong>sube el protocolo</strong>. Automatic Liquid Clustering / Predictive Optimization son <strong>Databricks</strong> (Unity Catalog managed). Este manual no lo toma como estándar OSS cotidiano: si lo activas en OSS, comprueba que <strong>todos</strong> los readers/writers entienden la feature. Aquí el camino base es partición bien elegida + <code>OPTIMIZE</code> + Z-Order puntual.</p><p>Siguiente: <a href="./07-streaming">Streaming</a>.</p>`,32)])])}const g=e(o,[["render",n]]);export{u as __pageData,g as default};
